(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.35) * 18 + Math.cos(y * 0.013 - t * 0.22) * 12;
  const w1y = Math.cos(y * 0.02 - t * 0.28) * 18 + Math.sin(x * 0.016 + t * 0.4) * 12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx * 0.01 + sy * 0.008 + t * 0.15) * 25;
  const w2y = Math.cos(sx * 0.008 - sy * 0.012 + t * 0.18) * 25;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.5)*110, 160+Math.sin(t*0.7)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.5+1)*95, 0.055, 2.4, 1.1],
    [120+Math.cos(t*0.8+1)*90, 180+Math.sin(t*0.6+3)*65, 0.11, 1.6, 0.85],
    [360+Math.sin(t*0.4+4)*100, 60+Math.cos(t*0.9+2)*75, 0.065, 2.7, 1.05],
    [240+Math.cos(t*0.35+5)*130, 200+Math.sin(t*0.55)*85, 0.085, 2.0, 0.95],
    [80+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65+2)*50, 0.1, 1.4, 0.8],
    [400+Math.cos(t*0.45+1)*80, 200+Math.sin(t*0.75+4)*60, 0.07, 2.5, 1.15],
    [200+Math.sin(t*0.7+6)*60, 220+Math.cos(t*0.3+5)*70, 0.12, 1.3, 0.75],
    [300+Math.cos(t*0.25+2)*100, 30+Math.sin(t*0.85+1)*40, 0.06, 2.8, 1.2]
  ];
  let aS = 0, iS = 0, totalW = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((fx-sX)**2 + (fy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    totalW += w;
  }
  const act = aS/totalW, inh = iS/totalW;
  const bg = (Math.sin(fx*0.035+fy*0.022+t*0.9) + Math.sin(fx*0.028-fy*0.038+t*1.2) + Math.sin(fx*0.015+fy*0.045-t*0.7))/3;
  const bg2 = Math.sin((fx+fy)*0.11+t*2.8)*0.25 + Math.sin((fx-fy)*0.09-t*2.2)*0.25;
  const dist = Math.sqrt((fx-cx)**2 + (fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.6) + Math.sin(dist*0.035+ang*4.5-t*1.3) + Math.sin(dist*0.06-ang*2-t*2.1))*0.3;
  const ring = Math.sin(dist*0.08-t*1.8)*Math.cos(ang*6+t*0.5)*0.15;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + bg2 + spiral + ring)*2.0);
  const cell = Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14) + Math.sin((fx+fy)*0.09+t)*0.5 + Math.sin(fx*0.07-fy*0.11+t*0.6)*0.3)*1.6)*0.3;
  const laplacian = (Math.sin(fx*0.2+1)*Math.cos(fy*0.2+2) + Math.sin((fx-2)*0.14)*Math.sin((fy+2)*0.14) + Math.sin((fx+2)*0.14)*Math.sin((fy-2)*0.14) - 2*Math.sin(fx*0.14)*Math.sin(fy*0.14))*0.15;
  const diffusion = Math.tanh(laplacian*3.0)*0.2;
  const blend = reaction*0.55 + cell*0.2 + diffusion*0.25;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,88],[18,95,125],[28,155,145],[65,185,135],
    [180,195,80],[220,170,60],[215,110,65],[175,55,70],[120,25,60],
    [60,15,48],[20,12,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const c0 = pal[i], c1 = pal[i+1];
  const lum = 0.78 + Math.sin(reaction*Math.PI)*0.22;
  const edge = Math.abs(reaction)>0.65 ? 1.12 + Math.abs(reaction)*0.08 : 1.0;
