    Math.min(255, ((c0[1]+(c1[1]-c0[1])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((c0[2]+(c1[2]-c0[2])*f)*lum*edge + glow*80)|0)
  ];
}
